import './motion.js';
const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = { grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z', board:'M3 4h18v16H3z M9 4v16 M15 4v16', list:'M8 6h13 M8 12h13 M8 18h13 M3 6h.1 M3 12h.1 M3 18h.1', bolt:'m13 2-9 12h7l-1 8 10-12h-7z', plus:'M12 5v14 M5 12h14', search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0', chevron:'m8 10 4 4 4-4', arrow:'M5 12h14 m-5-5 5 5-5 5', layers:'m12 3 10 5-10 5L2 8z M2 12l10 5 10-5 M2 16l10 5 10-5', connect:'m8 3 3 3-5 5-3-3 M6 6l-3-3 M13 13l5-5 3 3-5 5z M18 14l3 3 M8 16l8-8 M3 21l5-5', clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0', check:'m5 12 4 4L19 6', circle:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0', settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2', image:'M3 3h18v18H3z m0 14 5-5 4 4 3-3 6 6 M15 7h.1', activity:'M2 12h5l3-8 4 16 3-8h5', folder:'M3 6h7l2 2h9v12H3z M3 6V4h7l2 2', help:'M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 3 M12 17h.1 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0', close:'M6 6l12 12 M18 6 6 18', play:'m8 4 12 8-12 8z', stop:'M5 5h14v14H5z', download:'M12 3v12 m-5-5 5 5 5-5 M4 17v4h16v-4', file:'M5 2h9l5 5v15H5z M14 2v6h5 M8 12h8 M8 16h6', lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4', spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z', menu:'M3 6h18 M3 12h18 M3 18h18', code:'m8 5-6 7 6 7 m8-14 6 7-6 7', logout:'M9 3H3v18h6 M9 12h13 m-4-4 4 4-4 4' };
const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.circle}"/></svg>`;
const catalog = [
{id:'claude',name:'Claude Code',subtitle:'Anthropic',color:'clay',type:'cli',login:'claude auth login',capabilities:['Code','Research','Review']},
{id:'codex',name:'Codex',subtitle:'OpenAI',color:'mint',type:'cli',login:'codex login',capabilities:['Code','Debug','Review']},
{id:'gemini',name:'Gemini CLI',subtitle:'Google',color:'blue',type:'cli',login:'gemini',capabilities:['Research','Code','Review']},
{id:'cursor',name:'Cursor Agent',subtitle:'Cursor',color:'violet',type:'cli',login:'agent login',capabilities:['Code','Debug','Review']},
{id:'gemini-image',name:'Gemini API',subtitle:'Google AI Studio',color:'blue',type:'api',capabilities:['Images','Planning']}
];
const agent = id => data.providers?.find(p=>p.id===id) || catalog.find(p=>p.id===id);
const agentIcon = id => `<span class="agent-icon ${agent(id)?.color || ''}">${({claude:'✳',codex:'◉',gemini:'✦',cursor:'◈','gemini-image':'✧'})[id] || '–'}</span>`;
const now = Date.now();
const sample = {
 projects:[{id:'sample',name:'Launchpad website',context:'A thoughtful launch website for a new productivity app. Keep the experience clear, welcoming, and accessible. Use a calm visual language and focus on the product’s core value.',directory:'',sample:true}],
 tasks:[
 ['Explore the competitive landscape','Research','gemini','done','Map the category and identify opportunities for a distinctive product story.','Medium'],
 ['Define the visual direction','Design','claude','done','Create a cohesive visual language, typography, and color palette.','High'],
 ['Build the landing page','Frontend','codex','running','Turn the approved direction into a responsive, accessible homepage.','High'],
 ['Set up the waitlist API','Backend','claude','running','Create the signup endpoint, validation, and database schema.','High'],
 ['Create product illustrations','Images','gemini-image','review','A set of warm, minimal illustrations for the product features.','Medium'],
 ['Review the signup experience','Review','cursor','review','Check accessibility, edge cases, and the complete signup journey.','Medium'],
 ['Write the onboarding flow','Frontend','claude','queued','Make the first five minutes feel effortless for new users.','Medium'],
 ['Add analytics events','Backend','codex','queued','Track the key moments in the landing page conversion funnel.','Low']
 ].map((t,i)=>({id:'s'+i,projectId:'sample',title:t[0],category:t[1],provider:t[2],status:t[3],description:t[4],priority:t[5],dependencies:[],logs:[],createdAt:new Date(now-i*100000).toISOString(),sample:true})),
 assets:[],events:[{id:'e1',text:'Gemini Images finished product illustrations',provider:'gemini-image',at:new Date(now-120000).toISOString()},{id:'e2',text:'Codex started building the landing page',provider:'codex',at:new Date(now-300000).toISOString()},{id:'e3',text:'Claude Code completed the visual direction',provider:'claude',at:new Date(now-600000).toISOString()},{id:'e4',text:'Cursor Agent is reviewing the signup flow',provider:'cursor',at:new Date(now-900000).toISOString()}],connections:[],providers:catalog
};
let data = structuredClone(sample), serverData = null, online = false, demo = true, page = 'workspace', tab = 'board', view='board', projectId='sample', filter='', query='', currentTask=null, currentModal=null, busy=false, mobile=false, authRequired=false;
try { const saved=JSON.parse(localStorage.getItem('relay-demo')||'null'); if(saved) data={...saved,providers:catalog}; } catch {}
const project = () => data.projects.find(p=>p.id===projectId) || data.projects[0];
const tasks = () => data.tasks.filter(t=>t.projectId===project()?.id);
const reltime = date => { const mins=Math.max(0,Math.round((Date.now()-new Date(date))/60000)); return mins<1?'Just now':mins<60?`${mins}m ago`:mins<1440?`${Math.floor(mins/60)}h ago`:`${Math.floor(mins/1440)}d ago`; };
function toast(msg){ $('#toast').className='toast';$('#toast').textContent=msg;setTimeout(()=>{$('#toast').className='';$('#toast').textContent=''},4000); }
function saveDemo(){if(demo)localStorage.setItem('relay-demo',JSON.stringify(data));}
async function request(url,method='GET',body){const r=await fetch(url,{method,headers:{'Content-Type':'application/json','X-Relay-Token':serverData?.csrf||''},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Request failed');return d;}
async function refresh(initial=false){try{const r=await fetch('/api/state');if(r.status===401){online=true;authRequired=true;render();return;}if(!r.ok)throw new Error();const d=await r.json();if(!Array.isArray(d.projects))throw new Error();const unchanged = JSON.stringify(serverData)===JSON.stringify(d);online=true;authRequired=false;serverData=d;if(!demo){data=d;if(!projectId||!d.projects.some(p=>p.id===projectId))projectId=d.projects[0]?.id;}else data.providers=d.providers;if(initial&&d.projects.length){demo=false;data=d;projectId=d.projects[0].id;}if(!unchanged||initial)render();if(currentTask&&!busy)refreshDetail();}catch{if(initial){online=false;render();}else if(!demo)toast('Connection lost. Retrying…');}}
function empty(title,text,action='',label=''){return `<div class="empty">${icon('layers')}<h3>${title}</h3><p>${text}</p>${action?`<button class="btn primary" data-action="${action}">${icon('plus')}${label}</button>`:''}</div>`;}
function header(title,description,actions=''){return `<div class="page-header"><div><div class="eyebrow">Your agents. One workspace.</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div><div class="header-actions">${actions}</div></div>`;}
function render(){
 const activeTasks=tasks();const running=demo?0:data.tasks.filter(t=>t.status==='running').length;
 $('#app').innerHTML=`<div class="layout"><aside class="sidebar ${mobile?'open':''}"><div class="brand"><img src="syncfly-sync-wings.png" alt="">Syncfly</div><button class="workspace-switch" data-action="switch">${icon('layers')} ${demo?'Example workspace':esc(serverData?.user?.name||'My workspace')}${icon('chevron')}</button><div class="nav-label">WORKSPACE</div>${[['workspace','grid','Overview'],['connections','connect','Connections'],['activity','activity','Activity'],['assets','image','Assets']].map(([id,ic,label])=>`<button class="nav ${page===id?'active':''}" data-page="${id}">${icon(ic)}${label}${id==='connections'?`<span class="count">${data.connections?.length||0}</span>`:''}${id==='activity'&&running?`<span class="count">${running}</span>`:''}</button>`).join('')}<div class="projects-nav"><div class="nav-label" style="display:flex;justify-content:space-between">PROJECTS <button aria-label="Create project" data-action="new-project">+</button></div>${data.projects.map(p=>`<button class="nav ${projectId===p.id&&page==='workspace'?'active':''}" data-project="${esc(p.id)}"><span class="project-dot"></span><span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(p.name)}</span></button>`).join('')}<button class="nav" data-action="new-project">${icon('plus')}New project</button></div><div class="sidebar-bottom"><div class="local-card"><strong><span class="dot" style="${!online?'background:#b5bdab':''}"></span>${demo?'Explore the possibilities':serverData?.execution==='docker'?'Cloud runner':'Development runner'}</strong><p>${demo?'A sample project to see how your agents can work together. No agents are running.':'Your project, agents, and outputs. All together in one place.'}</p><button class="btn soft full" data-action="${demo?'start':'guide'}">${demo?'Create your workspace':'Workspace guide'}${icon('arrow')}</button></div><button class="nav" data-action="guide">${icon('help')}Help & getting started</button><div class="profile"><div class="avatar">${demo?'S':esc((serverData?.user?.name||'S').slice(0,2).toUpperCase())}</div><div><strong>${demo?'Your workspace':esc(serverData?.user?.name||'Syncfly workspace')}</strong><p>${demo?'Ready when you are':'Personal workspace'}</p></div>${!demo&&serverData?.user?`<button class="iconbtn" style="margin-left:auto" data-action="logout" aria-label="Sign out">${icon('logout')}</button>`:''}</div></div></aside><main class="main"><header class="topbar"><button class="iconbtn mobile-menu" aria-label="Toggle navigation" data-action="menu">${icon('menu')}</button><div class="breadcrumbs">Workspace <span>/</span><b>${page==='workspace'?esc(project()?.name||'Overview'):page[0].toUpperCase()+page.slice(1)}</b></div><div class="top-actions"><label class="searchbox">${icon('search')}<input id="search" placeholder="Search tasks…" value="${esc(query)}" aria-label="Search tasks"><kbd>/</kbd></label><button class="btn" data-action="guide">${icon('help')}Quick guide</button><div class="avatar">S</div></div></header><section class="page">${page==='workspace'?workspace():page==='connections'?connections():page==='assets'?assets():activity()}</section></main></div>`;
}
function workspace(){
 if(!project())return header('Let’s build something.','A shared home for your ideas and the agents that bring them to life.')+empty('Your first project starts here','Add a project, connect your favorite agents, and let a lead AI help break down the work.','new-project','Create project');
 const ts=tasks();const done=ts.filter(t=>t.status==='done').length;const active=ts.filter(t=>t.status==='running').length;const review=ts.filter(t=>t.status==='review').length;
 return `<div class="page-header"><div><div class="eyebrow">PROJECT WORKSPACE</div><h1>${esc(project().name)}${demo?'<span class="demo-pill">EXAMPLE PROJECT</span>':''}</h1><p>Different minds. Shared context. One place to move work forward.</p></div><div class="header-actions"><button class="btn" data-action="project-settings">${icon('settings')}Project settings</button><button class="btn primary" data-action="plan">${icon('spark')}Plan with AI</button></div></div>${demo?`<div class="intro"><div class="intro-symbol">${icon('layers')}</div><div><strong>A little coordination. A lot of possibility.</strong><p>Connect your agents, give them a goal, and bring their best work together.</p></div><button class="btn" data-action="start">Make it yours${icon('arrow')}</button></div>`:''}<div class="stats">${[['layers','Total tasks',ts.length,'Across this project'],['bolt',demo?'In progress · sample':'Agents working',active,demo?'Illustrative activity':'Running right now'],['clock','Ready for review',review,'Your eyes on the work'],['check','Completed',done,ts.length?`${Math.round(done/ts.length*100)}% of project`:'A fresh start']].map(([ic,title,num,note])=>`<div class="stat"><div class="stat-head">${icon(ic)}${title}</div><div class="stat-bottom"><span class="stat-number">${num.toString().padStart(2,'0')}</span><span class="stat-note">${note}</span>${ic==='check'?`<span class="progress"><i style="width:${ts.length?done/ts.length*100:0}%"></i></span>`:''}</div></div>`).join('')}</div><div class="tabs">${[['board','board','Task board'],['context','file','Shared context'],['assets','image','Project assets']].map(([id,ic,label])=>`<button class="tab ${tab===id?'active':''}" data-tab="${id}">${icon(ic)}${label}${id==='board'?`<span>${ts.length}</span>`:''}</button>`).join('')}</div>${tab==='context'?contextView():tab==='assets'?assets(true):`<div class="work-area"><div class="board-area"><div class="board-toolbar"><h3>All work <span class="muted small" style="font-weight:400;margin-left:5px">${ts.length}</span></h3><select class="select-filter" id="agent-filter" aria-label="Filter by agent"><option value="">All agents</option>${catalog.map(p=>`<option value="${p.id}" ${filter===p.id?'selected':''}>${p.name}</option>`).join('')}</select><button class="btn" style="min-height:29px;padding:6px 9px;font-size:10px" data-action="new-task">${icon('plus')}New task</button><div class="view-toggle"><button aria-label="Board view" data-view="board" class="${view==='board'?'active':''}">${icon('board')}</button><button aria-label="List view" data-view="list" class="${view==='list'?'active':''}">${icon('list')}</button></div></div><div id="task-content">${taskContent()}</div><div class="footnote">${icon('lock')}${demo?'Sample data only. Create a project to start real work.':'Each coding run works in its own isolated checkout. You review the result.'}</div></div>${rail()}</div>`}`;
}
function taskContent(){const ts=tasks().filter(t=>(!filter||t.provider===filter)&&`${t.title} ${t.description} ${t.category}`.toLowerCase().includes(query.toLowerCase()));if(view==='list')return ts.length?`<div class="table-wrap"><table><thead><tr><th>Task</th><th>Agent</th><th>Status</th><th>Priority</th></tr></thead><tbody>${ts.map(t=>`<tr data-task="${esc(t.id)}"><td><strong>${esc(t.title)}</strong><div style="margin-top:7px"><span class="tag ${esc(t.category)}">${esc(t.category)}</span></div></td><td>${esc(agent(t.provider)?.name||'Unassigned')}</td><td>${esc(t.status)}</td><td>${esc(t.priority)}</td></tr>`).join('')}</tbody></table></div>`:empty('No matching tasks','Try a different search or add a task.','new-task','New task');return `<div class="board">${[['queued','To do'],['running','In progress'],['review','In review'],['done','Done']].map(([status,label])=>{const items=ts.filter(t=>status==='queued'?['queued','failed','cancelled'].includes(t.status):t.status===status);return `<section class="column"><div class="column-head"><span class="status-dot ${status}"></span>${label}<span class="column-count">${items.length}</span><button data-action="new-task" aria-label="Add task">+</button></div>${items.map(card).join('')}<button class="add-task" data-action="new-task">${icon('plus')}Add task</button></section>`}).join('')}</div>`;}
function card(t){return `<button class="task-card" data-task="${esc(t.id)}"><div class="task-top"><span class="tag ${esc(t.category)}">${esc(t.category)}</span><span class="priority ${t.priority}" title="${t.priority} priority">▂▅▇</span></div><h3>${esc(t.title)}</h3><p>${esc(t.description||'Add instructions for your agent.')}</p>${t.status==='running'?`<div class="task-indicator"><i></i><i></i><i></i> ${demo?'Example run':'Working on it'}</div>`:t.status==='failed'?'<div class="task-indicator" style="color:#b47b69">Needs attention</div>':t.status==='review'?'<div class="task-indicator" style="color:#b19d6b">Ready for your review</div>':''}<div class="task-footer">${agentIcon(t.provider)}<span>${esc(agent(t.provider)?.name||'Unassigned')}</span><span class="mini-meta">${icon(t.dependencies?.length?'connect':'file')}${t.dependencies?.length||1}</span></div></button>`;}
function rail(){const events=demo?data.events:data.events.filter(e=>!e.taskId||tasks().some(t=>t.id===e.taskId));return `<aside class="activity-rail"><div class="rail-heading"><strong>Activity feed</strong><small>${demo?'SAMPLE':'LIVE'}</small></div>${events.slice(0,5).map(e=>`<div class="activity-item">${agentIcon(e.provider||data.tasks.find(t=>t.id===e.taskId)?.provider)}<p>${esc(e.text)}</p><time>${reltime(e.at)}</time></div>`).join('')||'<p class="small muted">Your project’s story will appear here.</p>'}<div class="rail-bottom">${icon('connect')}<strong>Better, together.</strong><p>Shared context keeps every agent working toward the same goal.</p></div></aside>`;}
function connections(){return header('Your AI team','Bring the agents you trust. Give each one room to do their best work.')+`<div class="notice">${demo?'Explore the available integrations. Create a workspace to connect real accounts.':'CLI accounts sign in through their provider’s official flow. Gemini API keys are stored on the server and are never sent back to your browser.'}</div><div class="connections">${catalog.map(p=>{const state=agent(p.id);const connected=!demo&&data.connections.includes(p.id);return `<article class="connection-card"><div class="connection-top">${agentIcon(p.id)}<div><h3>${p.name}</h3><p>${p.subtitle}</p></div></div><p>${p.type==='api'?'Generate images and draft project plans with your Gemini API key.':'Connect your account through the official agent. Assign it to any suitable task.'}</p><div class="chips">${p.capabilities.map(c=>`<span class="tag">${c}</span>`).join('')}</div><div class="connection-bottom"><span class="connection-status ${connected?'on':''}">${connected?'● Connected':demo?'Not connected':state?.installed?'Ready to connect':'Runner setup needed'}</span><button class="btn ${connected?'':'primary'}" data-connect="${p.id}">${connected?'Manage':'Connect'}${icon(connected?'settings':'plus')}</button></div></article>`}).join('')}<article class="connection-card" style="background:transparent;border-style:dashed"><div class="connection-top"><span class="agent-icon">+</span><div><h3>Room for more</h3><p>Built to be extensible</p></div></div><p>Providers are independent adapters. Add new integrations without changing how your team works.</p><div class="chips"><span class="tag">Provider-neutral</span><span class="tag">Flexible roles</span></div><button class="btn" data-action="guide">How Syncfly works${icon('arrow')}</button></article></div>`;}
function assets(inProject=false){const a=data.assets.filter(a=>!inProject||a.projectId===project()?.id);return (inProject?'':header('Project assets','The images and creative outputs your agents bring to life.',`<button class="btn primary" data-action="new-image">${icon('spark')}Generate image</button>`))+`<div class="asset-grid">${a.length?a.map(a=>`<article class="asset"><img src="/assets/${esc(a.filename)}" alt="${esc(a.title)}"><div class="asset-info"><div><h3>${esc(a.title)}</h3><p>${esc(a.model)} · ${reltime(a.at)}</p></div><a class="btn" href="/assets/${esc(a.filename)}" download aria-label="Download image">${icon('download')}</a></div></article>`).join(''):empty('A home for your next great idea','Connect Gemini API, describe an image, and find the finished result here.','new-image','Generate an image')}</div>`;}
function activity(){return header('Every move, in view','Follow task handoffs, completed work, and moments that need your attention.')+`<div class="context-panel">${data.events.length?data.events.map(e=>`<div class="activity-item">${agentIcon(e.provider||data.tasks.find(t=>t.id===e.taskId)?.provider)}<p>${esc(e.text)}</p><time>${new Date(e.at).toLocaleString()}</time>${e.taskId?`<button class="btn" style="margin-top:8px" data-task="${e.taskId}">View task${icon('arrow')}</button>`:''}</div>`).join(''):empty('A fresh activity feed','Updates appear here as your team starts working.')}</div>`;}
function contextView(){return `<div class="context-panel"><div style="display:flex;align-items:center;justify-content:space-between"><h2>A shared starting point</h2><button class="btn" data-action="project-settings">Edit context</button></div><p>${esc(project().context||'Add your goals, constraints, audience, and design direction. Every agent receives this context with its task.')}</p><div class="section-label">Repository</div><p class="mono">${esc(project().directory||project().repository||'No repository connected')}</p><div class="notice">Shared context and prerequisite task summaries travel with every assignment. Coding tasks run in isolated repository checkouts.</div></div>`;}
function modal(title,body,footer='',wide=false){currentModal=title;$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-header"><h2>${esc(title)}</h2><button class="iconbtn" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body"><div id="form-error" class="error hidden" role="alert"></div>${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;setTimeout(()=>$('#overlay input:not([type=checkbox]), #overlay textarea, #overlay button')?.focus(),30);}
function close(){currentTask=null;currentModal=null;$('#overlay').innerHTML='';}
function formError(msg){const e=$('#form-error');if(e){e.classList.remove('hidden');e.textContent=msg}else toast(msg);}
function field(label,name,placeholder='',value='',type='text',hint=''){return `<label class="form-field"><span>${label}</span><input type="${type}" name="${name}" placeholder="${esc(placeholder)}" value="${esc(value)}" ${type==='password'?'autocomplete="new-password"':''}>${hint?`<small>${hint}</small>`:''}</label>`;}
const cancel=`<button class="btn" data-action="close">Cancel</button>`;
function requireWorkspace(){if(!demo)return true;if(online&&authRequired){authModal();return false;}if(online){demo=false;data=serverData;projectId=data.projects[0]?.id;render();return true;}modal('Run your own Syncfly workspace',`<p>The hosted preview lets you explore Syncfly. Real agents run in your own cloud deployment.</p><div class="guide-step"><span class="number">1</span><div><strong>Deploy the Docker package</strong><p>Use the included Docker Compose configuration on a Linux server with Docker installed.</p></div></div><div class="guide-step"><span class="number">2</span><div><strong>Open your deployment</strong><p>Create your account, connect agents, and add a project. Your API keys stay on your server.</p></div></div><div class="code-block"><code>docker compose up -d --build</code></div><p>You can also keep exploring the sample workspace here.</p>`,cancel);return false;}
function projectModal(edit=false){if(!edit&&!requireWorkspace())return;const p=edit?project():{};modal(edit?'Project settings':'Create a project',`<form id="project-form">${field('Project name','name','e.g. A better booking experience',p.name||'')}<label class="form-field"><span>Shared context</span><textarea name="context" placeholder="What are we building? Who is it for? Add goals, constraints, and anything every agent should know.">${esc(p.context||'')}</textarea></label>${field('Git repository URL','repository','https://github.com/you/project.git',p.repository||'','url','Optional for planning and images. Public HTTPS repositories are supported in this version.')}${serverData?.execution==='native'?field('Or local repository path','directory','/absolute/path/to/repository',p.directory||''):''}<input type="hidden" name="id" value="${esc(edit?p.id:'')}"></form>`,`${cancel}<button class="btn primary" data-action="save-project">${edit?'Save changes':'Create project'}${icon('arrow')}</button>`);}
function taskModal(image=false){if(!demo&&!project())return projectModal();modal(image?'Generate an image':'Create a task',`<form id="task-form">${field(image?'Image title':'Task title','title',image?'e.g. Hero illustration':'What needs to get done?')}<label class="form-field"><span>${image?'Image prompt':'Instructions'}</span><textarea name="description" placeholder="${image?'Describe the subject, composition, style, colors, and intended use.':'Describe the expected result and how the agent should verify it.'}"></textarea></label><div class="form-row"><label class="form-field"><span>Assign to</span><select name="provider">${image?'<option value="gemini-image">Gemini Images · API</option>':'<option value="">Choose an agent</option>'+catalog.map(p=>`<option value="${p.id}">${p.name}${!demo&&!data.connections.includes(p.id)?' · not connected':''}</option>`).join('')}</select></label><label class="form-field"><span>Work section</span><select name="category">${['General','Research','Design','Frontend','Backend','Images','Debugging','Review'].map(s=>`<option ${image&&s==='Images'?'selected':''}>${s}</option>`).join('')}</select></label></div><div class="form-row">${field('Model (optional)','model',image?'gemini-3.1-flash-image':'Use provider default')}<label class="form-field"><span>${image?'Aspect ratio':'Priority'}</span><select name="${image?'aspectRatio':'priority'}">${(image?['1:1','16:9','9:16','4:3','3:4']:['Medium','High','Low']).map(v=>`<option>${v}</option>`).join('')}</select></label></div>${!image?`<label class="form-field"><span>Wait for task (optional)</span><select name="dependency"><option value="">No dependency</option>${tasks().map(t=>`<option value="${t.id}">${esc(t.title)}</option>`).join('')}</select></label><label class="check"><input type="checkbox" name="readOnly">Planning / read-only task</label>`:'<div class="notice">Gemini image requests use your API billing, separately from your Gemini app subscription.</div>'}</form>`,`${cancel}<button class="btn primary" data-action="save-task">Create task${icon('plus')}</button>`);}
function planModal(){if(!demo&&!project())return projectModal();modal('Give your AI team a goal',`<p>A lead agent will break your goal into clear tasks, assign suitable agents, and suggest dependencies. You review the plan before work starts.</p><form id="plan-form"><label class="form-field"><span>What would you like to build?</span><textarea name="objective" style="min-height:140px" placeholder="e.g. Build a booking flow with a searchable catalog, a reservation API, and friendly confirmation illustrations."></textarea></label><div class="form-row"><label class="form-field"><span>Lead agent</span><select name="provider">${catalog.map(p=>`<option value="${p.id}">${p.id==='gemini-image'?'Gemini API':p.name}${!demo&&!data.connections.includes(p.id)?' · not connected':''}</option>`).join('')}</select></label>${field('Model (optional)','model','Provider default')}</div></form>`,`${cancel}<button class="btn primary" data-action="generate-plan">${icon('spark')}Propose a plan</button>`);}
function connectModal(id){const p=agent(id);const connected=!demo&&data.connections.includes(id);modal(`${connected?'Manage':'Connect'} ${p.name}`,`${id==='gemini-image'?`<p>Add a Gemini API key to generate images and use Gemini as a lead planner. The key is validated with Google and stored only on your server.</p><form id="connection-form">${demo?'<div class="notice">Create a workspace in your Docker deployment to add a real API key.</div>':field('Gemini API key','key',connected?'Enter a replacement key':'Paste your API key','','password')}</form><p><a href="https://aistudio.google.com/apikey" target="_blank" rel="noopener noreferrer">Get a key in Google AI Studio ↗</a></p><div class="notice">API usage is billed by Google. Your Gemini app subscription does not automatically cover these requests.</div>`:`<p>Sign in through ${p.name}’s official authentication flow. Syncfly never asks for your account password.</p>${serverData?.execution==='docker'?`<div class="notice">Start sign-in below. The provider’s link or device code will appear here. Complete the provider flow, then verify the connection.</div><div id="login-output" class="log hidden"></div><label class="form-field hidden" id="login-answer"><span>Authorization code (if requested by the CLI)</span><input name="authCode" placeholder="Paste the provider’s authorization code"><small>Only needed when the official CLI asks for a code.</small></label><button class="btn hidden" id="send-code" data-action="send-code" data-provider="${id}">Submit code</button>`:`<div class="guide-step"><span class="number">1</span><div><strong>Sign in with the official CLI</strong><p>Run this in the terminal where Syncfly is installed.</p></div></div><div class="code-block"><code>${esc(p.login)}</code><button data-copy="${esc(p.login)}">Copy</button></div><div class="guide-step"><span class="number">2</span><div><strong>Verify the connection</strong><p>Syncfly uses the CLI’s saved login. Credentials remain with the provider.</p></div></div>`}${id==='gemini'?'<p class="small muted">Gemini sign-in is checked by its CLI on the first run.</p>':''}`}`,`${connected?`<button class="btn danger" data-disconnect="${id}">Disconnect</button>`:cancel}${id!=='gemini-image'&&serverData?.execution==='docker'?`<button class="btn" data-login="${id}">Start sign-in</button>`:''}<button class="btn primary" data-save-connection="${id}">${id==='gemini-image'?'Validate & save key':'Verify connection'}</button>`);}
function detail(id){currentTask=id;const t=data.tasks.find(t=>t.id===id);if(!t)return;modal(t.title,`<div id="detail-content">${detailContent(t)}</div>`, '',true);currentTask=id;}
function detailContent(t){const a=data.assets.filter(a=>a.taskId===t.id);return `<div class="detail-meta"><span class="tag ${esc(t.category)}">${esc(t.category)}</span>${agentIcon(t.provider)}<span class="small">${esc(agent(t.provider)?.name||'Unassigned')}</span><span class="tag">${esc(t.status)}</span>${demo?'<span class="tag">Sample task</span>':''}</div><p class="detail-body">${esc(t.description)}</p>${t.error?`<div class="error">${esc(t.error)}</div>`:''}${t.dependencies?.length?`<div class="notice">Waits for: ${t.dependencies.map(id=>esc(data.tasks.find(x=>x.id===id)?.title||'Unknown task')).join(', ')}</div>`:''}${demo?'<div class="notice">This is an illustrative task. Explore its details, or create a workspace to run real agents.</div>':''}${t.plan?`<div class="section-label">Proposed assignments</div><div class="table-wrap"><table><thead><tr><th>Task</th><th>Agent</th><th>Section</th></tr></thead><tbody>${t.plan.map(p=>`<tr><td>${esc(p.title)}</td><td>${esc(agent(p.provider)?.name||p.provider)}</td><td>${esc(p.category)}</td></tr>`).join('')}</tbody></table></div>`:''}<div class="section-label">Run output</div><div class="log" id="task-log">${t.logs?.length?t.logs.map(l=>`<div class="log-line"><time>${new Date(l.at).toLocaleTimeString()}</time>${esc(l.text)}</div>`).join(''):'No run output yet. Start this task to follow the agent’s progress.'}</div>${t.worktree?`<div class="section-label">Review workspace</div><div class="code-block"><code>${esc(t.branch)}<br>${esc(t.worktree)}</code></div><p class="small muted">Approval marks this task complete. It does not merge changes; review and merge the branch in your repository.</p>`:''}${a.length?`<div class="result-images">${a.map(a=>`<a href="/assets/${a.filename}" download><img src="/assets/${a.filename}" alt="${esc(a.title)}"></a>`).join('')}</div>`:''}<div class="detail-actions">${t.status==='running'?`<button class="btn danger" data-task-action="stop" data-id="${t.id}">${icon('stop')}Stop run</button>`:t.status==='review'?`<button class="btn primary" data-task-action="${t.plan?'accept-plan':'approve'}" data-id="${t.id}">${icon('check')}${t.plan?'Accept plan & create tasks':'Approve result'}</button>`:t.status!=='done'?`<button class="btn primary" data-task-action="run" data-id="${t.id}">${icon('play')}${t.status==='queued'?'Start task':'Retry task'}</button>`:''}${t.worktree?`<button class="btn" data-task-action="diff" data-id="${t.id}">${icon('code')}Review diff</button>`:''}${!t.sample&&t.status!=='running'&&!t.plan?`<select class="select-filter" id="reassign" data-id="${t.id}" aria-label="Reassign agent"><option value="">Reassign agent</option>${catalog.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select>`:''}<button class="btn" data-action="close">Close</button></div>`;}
function refreshDetail(){const t=data.tasks.find(t=>t.id===currentTask);if(t&&$('#detail-content'))$('#detail-content').innerHTML=detailContent(t);}
function authModal(register=true){modal(register?'Create your workspace':'Welcome back',`<p>Your account keeps your projects, provider connections, and outputs separate from other users on this server.</p><form id="auth-form">${register?field('Your name','name','Alex'):''}${field('Email','email','you@example.com','','email')}${field('Password','password','At least 12 characters','','password')}${register?field('Invitation code','invitation','Provided by your server owner','','password','Required for invitation-only deployments.'):''}<input type="hidden" name="mode" value="${register?'register':'login'}"></form>`, `<button class="btn" data-action="${register?'login-form':'register-form'}">${register?'Already have an account?':'Create an account'}</button><button class="btn primary" data-action="submit-auth">${register?'Create account':'Sign in'}</button>`);}
function guide(){modal('A workspace that works together',`<p>Syncfly brings your preferred agents into one project. Each connection is optional, and every role is yours to choose.</p>${[['Connect your agents','Use official CLI sign-in for account-based agents. Add a Gemini API key for images and API-based planning.'],['Give a lead AI the goal','Add a project and shared context. Your lead proposes tasks, agent assignments, and dependencies for your review.'],['Start ready tasks','Run independent assignments in parallel. Prerequisite tasks must be approved before their dependents can start.'],['Review the results','Watch the activity feed, inspect logs and diffs, download images, and approve finished work. Merge coding branches separately.']].map(([t,d],i)=>`<div class="guide-step"><span class="number">${i+1}</span><div><strong>${t}</strong><p>${d}</p></div></div>`).join('')}<div class="notice">Cloud deployment uses isolated runner containers. API billing and subscription limits remain with each provider.</div>`,`<button class="btn primary" data-action="close">Got it${icon('check')}</button>`);}
async function action(name,el){
 if(name==='close')return close();if(name==='menu'){mobile=!mobile;return render();}if(name==='guide')return guide();if(name==='switch'){if(!demo){demo=true;data=structuredClone(sample);projectId='sample';render();}else if(requireWorkspace()){render();if(!data.projects.length)projectModal();}return;}
 if(name==='start'){if(requireWorkspace()){render();projectModal();}return;}
 if(name==='new-project')return projectModal();if(name==='project-settings')return projectModal(true);if(name==='new-task')return taskModal();if(name==='new-image')return taskModal(true);if(name==='plan')return planModal();
 if(name==='login-form')return authModal(false);if(name==='register-form')return authModal(true);
 if(name==='logout'){await request('/api/auth/logout','POST');demo=true;data=structuredClone(sample);projectId='sample';await refresh();return;}
 if(name==='submit-auth'){const f=Object.fromEntries(new FormData($('#auth-form')));await request('/api/auth/'+f.mode,'POST',f);demo=false;close();await refresh();if(!data.projects.length)projectModal();return;}
 if(name==='save-project'){
 const f=Object.fromEntries(new FormData($('#project-form')));if(!f.name.trim())throw new Error('Give your project a name.');
 if(demo){Object.assign(project(),f);saveDemo();close();render();return toast('Sample project updated');}
 const p=await request('/api/projects',f.id?'PATCH':'POST',f);projectId=p.id;close();await refresh();page='workspace';render();return toast('Project saved');}
 if(name==='save-task'){const f=Object.fromEntries(new FormData($('#task-form')));if(!f.title.trim())throw new Error('Give your task a title.');f.projectId=project()?.id;f.dependencies=f.dependency?[f.dependency]:[];f.readOnly=f.readOnly==='on';
 if(demo){data.tasks.push({...f,id:crypto.randomUUID(),status:'queued',logs:[],sample:true});saveDemo();close();render();return toast('Added to the sample board');}
 if(!f.projectId)throw new Error('Create a project first.');await request('/api/tasks','POST',f);close();await refresh();return toast('Task ready to start');}
 if(name==='generate-plan'){
 const f=Object.fromEntries(new FormData($('#plan-form')));if(!f.objective.trim())throw new Error('Describe your goal first.');
 if(demo){modal('Example plan',`<p>A live lead agent will tailor tasks to your goal and connected providers. This preview illustrates the review step.</p><div class="notice">Goal: ${esc(f.objective)}</div>${[['Research the requirements','Research'],['Define the solution','Design'],['Implement the core experience','Frontend'],['Review and test the result','Review']].map(([t,c],i)=>`<div class="guide-step"><span class="number">${i+1}</span><div><strong>${t}</strong><p>${c} · lead suggests a suitable agent</p></div></div>`).join('')}`,`<button class="btn primary" data-action="start">Create a real workspace${icon('arrow')}</button>`);return;}
 const t=await request('/api/plan','POST',{...f,projectId:project().id});close();await refresh();detail(t.id);return;}
 if(name==='send-code'){const code=$('[name=authCode]')?.value;if(!code)throw new Error('Enter the requested authorization code.');await request('/api/login/'+el.dataset.provider+'/input','POST',{code});$('[name=authCode]').value='';toast('Code sent to official CLI');return;}
}
document.addEventListener('click',async e=>{const el=e.target.closest('button,[data-task],[data-copy]');if(!el)return;try{
 if(el.dataset.page){page=el.dataset.page;mobile=false;render();return;}if(el.dataset.project){projectId=el.dataset.project;page='workspace';tab='board';mobile=false;render();return;}if(el.dataset.tab){tab=el.dataset.tab;render();return;}if(el.dataset.view){view=el.dataset.view;render();return;}if(el.dataset.task)return detail(el.dataset.task);
 if(el.dataset.copy){await navigator.clipboard.writeText(el.dataset.copy);return toast('Copied');}
 if(el.dataset.connect)return connectModal(el.dataset.connect);
 if(el.dataset.saveConnection){if(demo){close();return requireWorkspace();}busy=true;el.disabled=true;await request('/api/connections','POST',{provider:el.dataset.saveConnection,key:$('[name=key]')?.value});close();await refresh();toast('Connection saved');return;}
 if(el.dataset.disconnect){await request('/api/connections','DELETE',{provider:el.dataset.disconnect});close();await refresh();toast('Disconnected');return;}
 if(el.dataset.login){busy=true;el.disabled=true;const id=el.dataset.login;await request('/api/login/'+id,'POST',{});$('#login-output').classList.remove('hidden');$('#login-answer').classList.remove('hidden');$('#send-code').classList.remove('hidden');pollLogin(id);return;}
 if(el.dataset.taskAction){const id=el.dataset.id;const a=el.dataset.taskAction;if(demo)return toast('Sample task only. Create a workspace to run real agents.');busy=true;el.disabled=true;if(a==='diff'){const d=await request(`/api/tasks/${id}/diff`);return modal('Review changes',`<pre class="log">${esc(d.diff)}${d.untracked?'\n\nUntracked files:\n'+esc(d.untracked):''}</pre><p style="margin-top:14px">New files are listed separately. Inspect them in the worktree before merging.</p>`,`<button class="btn" data-task="${id}">Back to task</button>`,true);}await request(`/api/tasks/${id}/${a}`,'POST',{});await refresh();refreshDetail();toast(a==='run'?'Task started':a==='accept-plan'?'Plan accepted. Tasks are ready to start.':'Task updated');return;}
 if(el.dataset.action){busy=true;await action(el.dataset.action,el);}
 }catch(err){formError(err.message);}finally{busy=false;el.disabled=false;}});
document.addEventListener('change',async e=>{if(e.target.id==='agent-filter'){filter=e.target.value;$('#task-content').innerHTML=taskContent();}if(e.target.id==='reassign'&&e.target.value){try{await request('/api/tasks/'+e.target.dataset.id,'PATCH',{provider:e.target.value});await refresh();refreshDetail();}catch(err){formError(err.message)}}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;if(page!=='workspace'){page='workspace';tab='board';render();$('#search')?.focus();}else if($('#task-content'))$('#task-content').innerHTML=taskContent();}});
document.addEventListener('submit',e=>e.preventDefault());
document.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#search')?.focus();}if(e.key==='Tab'&&$('#overlay .modal')){const nodes=[...$('#overlay .modal').querySelectorAll('button,a,input,textarea,select')].filter(n=>!n.disabled&&n.offsetParent!==null);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
async function pollLogin(id){try{const d=await request('/api/login/'+id);if(!$('#login-output'))return;$('#login-output').textContent=d.output||'Starting the official sign-in flow…';if(d.running)setTimeout(()=>pollLogin(id),1500);else toast('Sign-in process finished. Verify the connection.');}catch(e){formError(e.message);}}
render();refresh(true);setInterval(()=>{if(online&&!authRequired&&!busy&&!document.hidden)refresh();},4000);
